custom_css:
/* STANDALONE: Horizon Enterprise */

/* ==========================================================================
   WMN UNIVERSAL ERPNext THEME FOUNDATION
   Put this file in: UI Theme Setting -> fixed_css
   Theme-specific files only need to define tokens + signature styling.
   ========================================================================== */

:root {
  --ui-font: Inter, "Cairo", "Noto Sans Arabic", "Segoe UI", Arial, sans-serif;

  --ui-bg: #f5f6f8;
  --ui-surface: #ffffff;
  --ui-surface-2: #f8f9fb;
  --ui-surface-3: #eef1f5;

  --ui-text: #1f2933;
  --ui-muted: #68737d;
  --ui-subtle: #89939d;

  --ui-border: #dfe4e8;
  --ui-border-strong: #cbd3d9;

  --ui-accent: #2563eb;
  --ui-accent-2: #1d4ed8;
  --ui-accent-soft: rgba(37, 99, 235, .10);
  --ui-accent-soft-2: rgba(37, 99, 235, .06);

  --ui-success: #16835d;
  --ui-warning: #b7791f;
  --ui-danger: #c24141;
  --ui-info: #2563eb;

  --ui-navbar-bg: #18202a;
  --ui-navbar-text: #ffffff;
  --ui-navbar-muted: rgba(255,255,255,.72);

  --ui-sidebar-bg: #ffffff;
  --ui-sidebar-text: #39434d;
  --ui-sidebar-active-bg: var(--ui-accent-soft);
  --ui-sidebar-active-text: var(--ui-accent-2);

  --ui-field-bg: #ffffff;
  --ui-field-focus: var(--ui-accent);

  --ui-table-head-bg: #27313b;
  --ui-table-head-text: #ffffff;
  --ui-row-hover: var(--ui-accent-soft-2);

  --ui-radius-xs: 4px;
  --ui-radius-sm: 6px;
  --ui-radius-md: 9px;
  --ui-radius-lg: 12px;
  --ui-radius-xl: 16px;

  --ui-shadow-1: 0 1px 3px rgba(20, 28, 38, .06);
  --ui-shadow-2: 0 8px 24px rgba(20, 28, 38, .08);
  --ui-shadow-3: 0 18px 48px rgba(20, 28, 38, .14);

  --ui-navbar-height: 56px;
  --ui-system-sidebar-width: 232px;
  --ui-page-inline: 14px;
  --ui-page-gap: 14px;

  --ui-control-h: 38px;
  --ui-row-h: 44px;
  --ui-pagehead-h: 60px;

  --ui-transition: .16s ease;

  /* WMN navigation semantic bridge */
  --wmn-theme-nav-accent: var(--ui-accent);
  --wmn-theme-nav-on-accent: #fff;
  --wmn-theme-nav-navbar-bg: var(--ui-navbar-bg);
  --wmn-theme-nav-navbar-text: var(--ui-navbar-text);
  --wmn-theme-nav-surface: var(--ui-surface);
  --wmn-theme-nav-page-bg: var(--ui-bg);
  --wmn-theme-nav-text: var(--ui-text);
  --wmn-theme-nav-muted: var(--ui-muted);
  --wmn-theme-nav-border: var(--ui-border);
  --wmn-theme-nav-radius: var(--ui-radius-md);
  --wmn-theme-nav-hover-bg: var(--ui-accent-soft-2);
  --wmn-theme-nav-active-bg: var(--ui-accent-soft);
  --wmn-theme-nav-sidebar-hover: var(--ui-accent-soft);
  --wmn-theme-nav-sidebar-sub-bg: rgba(0,0,0,.10);

  --wmn-theme-topbar-bg: var(--ui-navbar-bg);
  --wmn-theme-topbar-menu-bg: var(--ui-navbar-bg);
  --wmn-theme-topbar-text: var(--ui-navbar-muted);
  --wmn-theme-topbar-hover-text: var(--ui-navbar-text);
  --wmn-theme-topbar-active: var(--ui-accent);
  --wmn-theme-topbar-hover-bg: rgba(255,255,255,.07);
  --wmn-theme-topbar-border: rgba(255,255,255,.10);
  --wmn-theme-topbar-menu-shadow: var(--ui-shadow-3);
}

/* ------------------------------ Reset ------------------------------ */
html, body { min-height: 100%; }
body:not(.wmn-mamsek-pos-route) {
  margin: 0 !important;
  min-height: 100vh;
  min-height: 100dvh;
  font-family: var(--ui-font) !important;
  font-size: 14px !important;
  color: var(--ui-text) !important;
  background: var(--ui-bg) !important;
  -webkit-font-smoothing: antialiased;
}
body:not(.wmn-mamsek-pos-route) *,
body:not(.wmn-mamsek-pos-route) *::before,
body:not(.wmn-mamsek-pos-route) *::after { box-sizing: border-box; }
body:not(.wmn-mamsek-pos-route) a { color: var(--ui-accent); text-decoration: none; }
body:not(.wmn-mamsek-pos-route) a:hover { color: var(--ui-accent-2); }
body:not(.wmn-mamsek-pos-route) ::selection { background: var(--ui-accent-soft); }

/* Scrollbars */
body:not(.wmn-mamsek-pos-route) ::-webkit-scrollbar { width: 9px; height: 9px; }
body:not(.wmn-mamsek-pos-route) ::-webkit-scrollbar-track { background: transparent; }
body:not(.wmn-mamsek-pos-route) ::-webkit-scrollbar-thumb {
  border: 2px solid transparent;
  border-radius: 999px;
  background: color-mix(in srgb, var(--ui-muted) 55%, transparent);
  background-clip: padding-box;
}

/* ------------------------------ ERP navbar ------------------------------ */
body:not(.wmn-mamsek-pos-route) header.navbar,
body:not(.wmn-mamsek-pos-route) .navbar {
  position: sticky !important;
  top: 0 !important;
  z-index: 1040 !important;
  width: 100% !important;
  min-height: var(--ui-navbar-height) !important;
  height: var(--ui-navbar-height) !important;
  padding: 0 !important;
  border: 0 !important;
  background: var(--ui-navbar-bg) !important;
  color: var(--ui-navbar-text) !important;
  box-shadow: var(--ui-shadow-1) !important;
}
body:not(.wmn-mamsek-pos-route) header.navbar > .container,
body:not(.wmn-mamsek-pos-route) header.navbar > .container-fluid,
body:not(.wmn-mamsek-pos-route) .navbar > .container,
body:not(.wmn-mamsek-pos-route) .navbar > .container-fluid {
  width: 100% !important;
  max-width: none !important;
  height: var(--ui-navbar-height) !important;
  margin: 0 !important;
  padding-inline: 18px !important;
}
body:not(.wmn-mamsek-pos-route) .navbar .navbar-brand,
body:not(.wmn-mamsek-pos-route) .navbar .navbar-home,
body:not(.wmn-mamsek-pos-route) .navbar .nav-link,
body:not(.wmn-mamsek-pos-route) .navbar .dropdown-toggle,
body:not(.wmn-mamsek-pos-route) .navbar #navbar-breadcrumbs a,
body:not(.wmn-mamsek-pos-route) .navbar button.btn-reset.nav-link,
body:not(.wmn-mamsek-pos-route) .navbar button.btn-reset.nav-link span {
  color: var(--ui-navbar-text) !important;
}
body:not(.wmn-mamsek-pos-route) .navbar #navbar-search {
  min-height: 36px !important;
  border: 1px solid rgba(255,255,255,.14) !important;
  border-radius: var(--ui-radius-md) !important;
  background: rgba(255,255,255,.08) !important;
  color: var(--ui-navbar-text) !important;
  box-shadow: none !important;
}
body:not(.wmn-mamsek-pos-route) .navbar #navbar-search::placeholder { color: var(--ui-navbar-muted) !important; }
body:not(.wmn-mamsek-pos-route) .navbar #navbar-search:focus {
  border-color: color-mix(in srgb, var(--ui-accent) 75%, #fff) !important;
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--ui-accent) 22%, transparent) !important;
}
body:not(.wmn-mamsek-pos-route) .navbar .navbar-nav > li > a,
body:not(.wmn-mamsek-pos-route) .navbar .navbar-nav > li > button {
  border-radius: var(--ui-radius-sm) !important;
}
body:not(.wmn-mamsek-pos-route) .navbar .navbar-nav > li > a:hover,
body:not(.wmn-mamsek-pos-route) .navbar .navbar-nav > li > button:hover {
  background: rgba(255,255,255,.08) !important;
}

/* ------------------------------ WMN top bar ------------------------------ */
.wmn-global-workspace-header,
.wmn-dashboard-header {
  background: var(--wmn-theme-topbar-bg) !important;
  color: var(--wmn-theme-topbar-text) !important;
  box-shadow: none !important;
}
.wmn-global-workspace-header { border-bottom: 1px solid var(--wmn-theme-topbar-border) !important; }
.wmn-dashboard-header { border-bottom: 1px solid var(--wmn-theme-topbar-border) !important; }
.wmn-dashboard-header .wmn-workspace-btn {
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
  color: var(--wmn-theme-topbar-text) !important;
}
.wmn-dashboard-header .wmn-workspace-btn:hover {
  background: var(--wmn-theme-topbar-hover-bg) !important;
  color: var(--wmn-theme-topbar-hover-text) !important;
}
.wmn-dashboard-header .wmn-workspace-btn.active {
  background: transparent !important;
  color: var(--wmn-theme-topbar-active) !important;
}
.wmn-dashboard-header .wmn-workspace-btn.active::after { background: var(--wmn-theme-topbar-active) !important; }
.wmn-workspace-overflow,
.wmn-workspace-overflow-btn {
  background: var(--wmn-theme-topbar-bg) !important;
  color: var(--wmn-theme-topbar-text) !important;
}
.wmn-workspace-overflow-btn:hover,
.wmn-workspace-overflow-btn.active {
  background: var(--wmn-theme-topbar-hover-bg) !important;
  color: var(--wmn-theme-topbar-hover-text) !important;
}
.wmn-workspace-overflow-menu {
  background: var(--wmn-theme-topbar-menu-bg) !important;
  border-color: var(--wmn-theme-topbar-border) !important;
  box-shadow: var(--wmn-theme-topbar-menu-shadow) !important;
}
.wmn-workspace-overflow-item { background: transparent !important; color: var(--wmn-theme-topbar-text) !important; }
.wmn-workspace-overflow-item:hover { background: var(--wmn-theme-topbar-hover-bg) !important; color: var(--wmn-theme-topbar-hover-text) !important; }
.wmn-workspace-overflow-item.active { color: var(--wmn-theme-topbar-active) !important; }
.wmn-toggle-header-btn {
  background: var(--wmn-theme-topbar-bg) !important;
  color: var(--wmn-theme-topbar-text) !important;
  border-color: var(--wmn-theme-topbar-border) !important;
}

/* ------------------------------ WMN custom sidebar ------------------------------ */
.wmn-custom-sidebar {
  background: var(--wmn-theme-nav-navbar-bg) !important;
  color: var(--wmn-theme-nav-navbar-text) !important;
  border-inline-end: 1px solid color-mix(in srgb, var(--wmn-theme-nav-navbar-text) 10%, transparent) !important;
  box-shadow: 8px 0 26px rgba(0,0,0,.18) !important;
}
.wmn-user-section { border-bottom-color: color-mix(in srgb, var(--wmn-theme-nav-navbar-text) 10%, transparent) !important; }
.wmn-user-info,
.wmn-module-header,
.wmn-sidebar-workspace-header,
.wmn-sidebar-card-header,
.wmn-sidebar-link,
.wmn-menu-text { color: var(--wmn-theme-nav-navbar-text) !important; }
.wmn-user-info i,
.wmn-module-header i,
.wmn-sidebar-workspace-header i,
.wmn-sidebar-card-header i,
.wmn-sidebar-link i { color: var(--wmn-theme-nav-accent) !important; }
.wmn-module-header:hover,
.wmn-sidebar-workspace-header:hover,
.wmn-sidebar-card-header:hover,
.wmn-sidebar-link:hover { background: var(--wmn-theme-nav-sidebar-hover) !important; }
.wmn-module-header::before,
.wmn-sidebar-workspace-header::before,
.wmn-sidebar-card-header::before,
.wmn-sidebar-link::before { background: var(--wmn-theme-nav-accent) !important; }
.wmn-module-content,
.wmn-sidebar-workspace-content,
.wmn-sidebar-card-content { background: var(--wmn-theme-nav-sidebar-sub-bg) !important; }
.wmn-floating-sidebar-btn {
  background: var(--wmn-theme-nav-navbar-bg) !important;
  color: var(--wmn-theme-nav-navbar-text) !important;
  border-color: color-mix(in srgb, var(--wmn-theme-nav-navbar-text) 12%, transparent) !important;
}

/* ------------------------------ True full width ------------------------------ */
body:not(.wmn-mamsek-pos-route) .page-container,
body:not(.wmn-mamsek-pos-route) .page-body,
body:not(.wmn-mamsek-pos-route) .page-content {
  width: 100% !important;
  max-width: none !important;
  min-width: 0 !important;
  margin: 0 !important;
}
body:not(.wmn-mamsek-pos-route) .page-container {
  min-height: calc(100vh - var(--ui-navbar-height)) !important;
  min-height: calc(100dvh - var(--ui-navbar-height)) !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: var(--ui-bg) !important;
  box-shadow: none !important;
}
body:not(.wmn-mamsek-pos-route) .page-container > .container,
body:not(.wmn-mamsek-pos-route) .page-container > .container-fluid,
body:not(.wmn-mamsek-pos-route) .page-body > .container,
body:not(.wmn-mamsek-pos-route) .page-body > .container-fluid,
body:not(.wmn-mamsek-pos-route) .page-head > .container,
body:not(.wmn-mamsek-pos-route) .page-head > .container-fluid,
body:not(.wmn-mamsek-pos-route) .page-head .container,
body:not(.wmn-mamsek-pos-route) .page-head .container-fluid {
  width: 100% !important;
  max-width: none !important;
  margin-inline: 0 !important;
}
body:not(.wmn-mamsek-pos-route) .page-body > .container,
body:not(.wmn-mamsek-pos-route) .page-body > .container-fluid {
  padding-inline: var(--ui-page-inline) !important;
}

/* ------------------------------ Page head ------------------------------ */
body:not(.wmn-mamsek-pos-route) .page-head {
  min-height: var(--ui-pagehead-h) !important;
  margin: 0 !important;
  border: 0 !important;
  border-bottom: 1px solid var(--ui-border) !important;
  background: var(--ui-surface) !important;
  color: var(--ui-text) !important;
  box-shadow: var(--ui-shadow-1) !important;
}
body:not(.wmn-mamsek-pos-route) .page-head .container,
body:not(.wmn-mamsek-pos-route) .page-head .container-fluid {
  min-height: var(--ui-pagehead-h) !important;
  padding-inline: 16px !important;
}
body:not(.wmn-mamsek-pos-route) .page-title,
body:not(.wmn-mamsek-pos-route) .page-title .title-text,
body:not(.wmn-mamsek-pos-route) .page-head h3,
body:not(.wmn-mamsek-pos-route) .page-head h4 {
  color: var(--ui-text) !important;
  font-weight: 700 !important;
}

/* ------------------------------ Desktop layout ------------------------------ */
@media (min-width: 992px) {
  body:not(.wmn-mamsek-pos-route) .layout-main {
    display: flex !important;
    flex-direction: row !important;
    flex-wrap: nowrap !important;
    align-items: flex-start !important;
    width: 100% !important;
    max-width: none !important;
    min-width: 0 !important;
    gap: var(--ui-page-gap) !important;
    margin: 0 !important;
    padding: var(--ui-page-gap) 0 24px !important;
  }
  body:not(.wmn-mamsek-pos-route) .layout-main > .layout-side-section {
    flex: 0 0 var(--ui-system-sidebar-width) !important;
    width: var(--ui-system-sidebar-width) !important;
    min-width: var(--ui-system-sidebar-width) !important;
    max-width: var(--ui-system-sidebar-width) !important;
    margin: 0 !important;
    align-self: stretch !important;
  }
  body:not(.wmn-mamsek-pos-route) .layout-main > .layout-main-section-wrapper {
    flex: 1 1 0 !important;
    width: auto !important;
    min-width: 0 !important;
    max-width: none !important;
    margin: 0 !important;
    padding: 0 !important;
  }
  body:not(.wmn-mamsek-pos-route) .layout-main .layout-main-section {
    width: 100% !important;
    max-width: none !important;
    min-width: 0 !important;
    margin: 0 !important;
  }
}

/* ------------------------------ System sidebar ------------------------------ */
body:not(.wmn-mamsek-pos-route) .layout-side-section,
body:not(.wmn-mamsek-pos-route) .desk-sidebar,
body:not(.wmn-mamsek-pos-route) .sidebar,
body:not(.wmn-mamsek-pos-route) .standard-sidebar {
  color: var(--ui-sidebar-text) !important;
  background: var(--ui-sidebar-bg) !important;
}
body:not(.wmn-mamsek-pos-route) .layout-main > .layout-side-section {
  padding: 12px 9px !important;
  border: 1px solid var(--ui-border) !important;
  border-radius: var(--ui-radius-lg) !important;
  box-shadow: var(--ui-shadow-1) !important;
}
body:not(.wmn-mamsek-pos-route) .sidebar-item,
body:not(.wmn-mamsek-pos-route) .desk-sidebar-item,
body:not(.wmn-mamsek-pos-route) .standard-sidebar-item,
body:not(.wmn-mamsek-pos-route) .layout-side-section .sidebar-menu > li > a {
  min-height: 38px !important;
  margin-block: 2px !important;
  padding: 7px 9px !important;
  border: 1px solid transparent !important;
  border-radius: var(--ui-radius-sm) !important;
  background: transparent !important;
  color: var(--ui-sidebar-text) !important;
  font-weight: 550 !important;
  transition: all var(--ui-transition) !important;
}
body:not(.wmn-mamsek-pos-route) .sidebar-item:hover,
body:not(.wmn-mamsek-pos-route) .desk-sidebar-item:hover,
body:not(.wmn-mamsek-pos-route) .standard-sidebar-item:hover,
body:not(.wmn-mamsek-pos-route) .sidebar-item.selected,
body:not(.wmn-mamsek-pos-route) .desk-sidebar-item.selected,
body:not(.wmn-mamsek-pos-route) .standard-sidebar-item.selected,
body:not(.wmn-mamsek-pos-route) .sidebar-item.active {
  background: var(--ui-sidebar-active-bg) !important;
  color: var(--ui-sidebar-active-text) !important;
}

/* ------------------------------ Main content surface ------------------------------ */
body:not(.wmn-mamsek-pos-route) .layout-main-section {
  border: 1px solid var(--ui-border) !important;
  border-radius: var(--ui-radius-lg) !important;
  background: var(--ui-surface) !important;
  box-shadow: var(--ui-shadow-1) !important;
}
body:not(.wmn-mamsek-pos-route) .form-layout,
body:not(.wmn-mamsek-pos-route) .form-page,
body:not(.wmn-mamsek-pos-route) .list-view-container,
body:not(.wmn-mamsek-pos-route) .frappe-list,
body:not(.wmn-mamsek-pos-route) .report-wrapper,
body:not(.wmn-mamsek-pos-route) .query-report,
body:not(.wmn-mamsek-pos-route) .workspace-container,
body:not(.wmn-mamsek-pos-route) .workspace-body,
body:not(.wmn-mamsek-pos-route) .workspace-content {
  width: 100% !important;
  max-width: none !important;
  min-width: 0 !important;
}

/* ------------------------------ Workspaces / widgets ------------------------------ */
body:not(.wmn-mamsek-pos-route) .workspace-container,
body:not(.wmn-mamsek-pos-route) .workspace-body,
body:not(.wmn-mamsek-pos-route) .workspace-content { background: transparent !important; }
body:not(.wmn-mamsek-pos-route) .widget,
body:not(.wmn-mamsek-pos-route) .card-item,
body:not(.wmn-mamsek-pos-route) .links-widget-box,
body:not(.wmn-mamsek-pos-route) .shortcut-widget-box,
body:not(.wmn-mamsek-pos-route) .number-widget-box,
body:not(.wmn-mamsek-pos-route) .dashboard-widget-box,
body:not(.wmn-mamsek-pos-route) .dashboard-card,
body:not(.wmn-mamsek-pos-route) .number-card,
body:not(.wmn-mamsek-pos-route) .number-card-container,
body:not(.wmn-mamsek-pos-route) .chart-container,
body:not(.wmn-mamsek-pos-route) .chart-wrapper {
  border: 1px solid var(--ui-border) !important;
  border-radius: var(--ui-radius-lg) !important;
  background: var(--ui-surface) !important;
  box-shadow: var(--ui-shadow-1) !important;
  transition: border-color var(--ui-transition), box-shadow var(--ui-transition), transform var(--ui-transition) !important;
}
body:not(.wmn-mamsek-pos-route) .shortcut-widget-box:hover,
body:not(.wmn-mamsek-pos-route) .number-widget-box:hover,
body:not(.wmn-mamsek-pos-route) .card-item:hover,
body:not(.wmn-mamsek-pos-route) .links-widget-box:hover {
  border-color: color-mix(in srgb, var(--ui-accent) 35%, var(--ui-border)) !important;
  box-shadow: var(--ui-shadow-2) !important;
}
body:not(.wmn-mamsek-pos-route) .widget-head,
body:not(.wmn-mamsek-pos-route) .widget-title,
body:not(.wmn-mamsek-pos-route) .card-header,
body:not(.wmn-mamsek-pos-route) .card-title,
body:not(.wmn-mamsek-pos-route) .widget-group-title {
  color: var(--ui-text) !important;
  font-weight: 700 !important;
}
body:not(.wmn-mamsek-pos-route) .workspace-item,
body:not(.wmn-mamsek-pos-route) .clink-item {
  border-radius: var(--ui-radius-sm) !important;
  color: var(--ui-text) !important;
}
body:not(.wmn-mamsek-pos-route) .workspace-item:hover,
body:not(.wmn-mamsek-pos-route) .clink-item:hover { background: var(--ui-accent-soft-2) !important; }
body:not(.wmn-mamsek-pos-route) .menu-text,
body:not(.wmn-mamsek-pos-route) .clink-item,
body:not(.wmn-mamsek-pos-route) .clink-item span { color: var(--ui-text) !important; }

/* ------------------------------ Buttons ------------------------------ */
body:not(.wmn-mamsek-pos-route) .btn {
  min-height: var(--ui-control-h) !important;
  padding-inline: 12px !important;
  border: 1px solid var(--ui-border-strong) !important;
  border-radius: var(--ui-radius-md) !important;
  background: var(--ui-surface) !important;
  color: var(--ui-text) !important;
  font-size: 13px !important;
  font-weight: 650 !important;
  box-shadow: none !important;
  transition: all var(--ui-transition) !important;
}
body:not(.wmn-mamsek-pos-route) .btn:hover {
  border-color: color-mix(in srgb, var(--ui-accent) 45%, var(--ui-border)) !important;
  background: var(--ui-accent-soft-2) !important;
  color: var(--ui-accent-2) !important;
}
body:not(.wmn-mamsek-pos-route) .btn-primary,
body:not(.wmn-mamsek-pos-route) .btn.btn-primary,
body:not(.wmn-mamsek-pos-route) .primary-action {
  border-color: var(--ui-accent) !important;
  background: var(--ui-accent) !important;
  color: #fff !important;
}
body:not(.wmn-mamsek-pos-route) .btn-primary:hover,
body:not(.wmn-mamsek-pos-route) .btn.btn-primary:hover,
body:not(.wmn-mamsek-pos-route) .primary-action:hover {
